function partitionString(s) {
  const seen = new Set();
  const segments = [];
  let current = '';
  for (const char of s) {
    current += char;
    if (!seen.has(current)) {
      seen.add(current);
      segments.push(current);
      current = '';
    }
  }
  return segments;
}

