function partitionString(s) {
  // Each segment is the shortest prefix of the rest of s that is not already in the list; stop when none exists.
  const segments = [];
  let start = 0;
  while (start < s.length) {
    let length = 1;
    while (start + length <= s.length && segments.includes(s.slice(start, start + length))) length++;
    if (start + length > s.length) break;
    segments.push(s.slice(start, start + length));
    start += length;
  }
  return segments;
}

