function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 10000 : int(1, 12);
  const letters = [1, 2, 3, 26][int(0, 3)];
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + int(0, letters - 1));
  return [s];
}
